// R5 frozen scalar exact 14-label joint two-extension f=0 census.
// Distinct named hypotheses; full joint interval-maximal observation masks.
// Science SHA256: 50e87f0194cfb3780e84b7bbb6f9a2dca4f79bb4901cab06f1a5b59256fb470b
#include <bits/stdc++.h>
using namespace std;
static constexpr int N=256,Q=101,K=14,FULL=(1<<K)-1;
static constexpr int W[12]={0,16,32,48,1,64,17,80,18,24,34,82};
struct Act {int k;vector<int> ms;};
using Sig=vector<Act>;
vector<int> maximal(vector<int> ms){sort(ms.begin(),ms.end());ms.erase(unique(ms.begin(),ms.end()),ms.end());vector<int> out;for(int m:ms){bool sub=false;for(int n:ms)if(n!=m && (m&n)==m){sub=true;break;}if(!sub)out.push_back(m);}return out;}
Sig signature(const vector<uint8_t>& adj,int u,int v){int h[K];copy(begin(W),end(W),h);h[12]=u;h[13]=v;map<vector<int>,int> groups;
 for(int j=0;j<Q;j++){const uint8_t* p=adj.data()+(size_t)j*N*N;vector<int> ms;for(int i=0;i<K;i++){int m=0;for(int t=0;t<K;t++)if(p[h[i]*N+h[t]])m|=1<<t;ms.push_back(m);}auto maxms=maximal(move(ms));if(maxms.size()==1&&maxms[0]==FULL)continue;auto it=groups.find(maxms);if(it==groups.end()||it->second>214+j)groups[maxms]=214+j;}
 Sig a;for(auto& [ms,cost]:groups)a.push_back({cost,ms});sort(a.begin(),a.end(),[](const Act& x,const Act& y){return x.k<y.k;});return a;}
string sigkey(const Sig& a){string s;for(auto&act:a){s+=to_string(act.k);s+=':';for(int m:act.ms){s+=to_string(m);s+=',';}s+=';';}return s;}
struct Solve {const Sig& acts;int memo[1<<K];long long visits=0;Solve(const Sig& a):acts(a){fill(begin(memo),end(memo),-1);memo[0]=0;for(int i=0;i<K;i++)memo[1<<i]=0;}
int V(int live){if(memo[live]>=0)return memo[live];visits++;int best=1000000;
 for(const auto& a:acts){int worst=0;bool stall=0;for(int m:a.ms){int nxt=m&live;if(nxt==live){stall=1;break;}if(a.k+worst>=best)break;worst=max(worst,V(nxt));}
 if(!stall)best=min(best,a.k+worst);}
 if(best==1000000)throw runtime_error("NO_PROGRESS");return memo[live]=best;}
};
int main(int argc,char**argv){if(argc<3){cerr<<"USAGE window_adj.bin output.csv [maxpairs (0=all)]\n";return 2;}ifstream fi(argv[1],ios::binary);vector<uint8_t> adj((size_t)Q*N*N);fi.read((char*)adj.data(),adj.size());if(!fi||fi.gcount()!=(streamsize)adj.size()){cerr<<"BAD_ADJ\n";return 3;}
 bool used[N]={};for(int h:W)used[h]=true;vector<int> others;for(int i=0;i<N;i++)if(!used[i])others.push_back(i);
 int maxpairs=(argc>=4)?stoi(argv[3]):0;ofstream out(argv[2]);out<<"u,v,f0,signature_class\n";unordered_map<string,pair<int,int>> cache;map<int,int> dist;long long totalstates=0;int pairs=0;auto start=chrono::steady_clock::now();
 for(int i=0;i<(int)others.size();i++)for(int j=i+1;j<(int)others.size();j++){int u=others[i],v=others[j];auto a=signature(adj,u,v);auto key=sigkey(a);int val,cl;auto it=cache.find(key);if(it==cache.end()){Solve s(a);val=s.V(FULL);totalstates+=s.visits;cl=(int)cache.size();cache.emplace(move(key),make_pair(val,cl));}else{val=it->second.first;cl=it->second.second;}out<<u<<","<<v<<","<<val<<","<<cl<<"\n";dist[val]++;pairs++;if(maxpairs>0&&pairs>=maxpairs)goto done;}
 done: out.flush();cerr<<"pairs="<<pairs<<" signatures="<<cache.size()<<" solved_states="<<totalstates<<" seconds="<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<"\n";for(auto [cost,num]:dist)cerr<<"V0="<<cost<<" count="<<num<<"\n";return 0;}
